import i18n from "i18next";
import LanguageDetector from "i18next-browser-languagedetector";
import { initReactI18next } from "react-i18next";
import frSkills from "./resources/fr/skills";
import enSkills from "./resources/en/skills";
import frProjects from "./resources/fr/projects";
import enProjects from "./resources/en/projects";
import frCommon from "./resources/fr/common";
import frHome from "./resources/fr/home";
import frAbout from "./resources/fr/about";
import frCv from "./resources/fr/cv";
import frContact from "./resources/fr/contact";
import enCommon from "./resources/en/common";
import enHome from "./resources/en/home";
import enAbout from "./resources/en/about";
import enCv from "./resources/en/cv";
import enContact from "./resources/en/contact";

function updateDocument(language: string) {
  document.documentElement.lang = language.split("-")[0] === "en" ? "en" : "fr";
}

i18n.on("languageChanged", updateDocument);
i18n.use(LanguageDetector).use(initReactI18next).init({
  resources: {
    fr: { skills: frSkills, projects: frProjects, common: frCommon, home: frHome, about: frAbout, cv: frCv, contact: frContact },
    en: { skills: enSkills, projects: enProjects, common: enCommon, home: enHome, about: enAbout, cv: enCv, contact: enContact },
  },
  supportedLngs: ["fr", "en"],
  fallbackLng: "fr",
  load: "languageOnly",
  nonExplicitSupportedLngs: true,
  defaultNS: "common",
  returnNull: false,
  initImmediate: false,
  detection: { order: ["localStorage", "navigator"], caches: ["localStorage"] },
  interpolation: { escapeValue: false },
});
updateDocument(i18n.resolvedLanguage || "fr");

export default i18n;
