import { Box } from "@mui/material";
import styles from "./styles";
import CardContent from "./sub_components/card_content";

import type { ResumeCardProps } from "./types";

export default function ResumeCard({image, imageLoading, imageSrcSet, imageSizes, imageFit = "cover", technologies, period, title, description, headingLevel = "h3", action }: ResumeCardProps) {

  return (
    <Box sx={styles.card}>
      {image && <Box
        component="img"
        src={image}
        loading={imageLoading}
        decoding="async"
        srcSet={imageSrcSet}
        sizes={imageSrcSet ? imageSizes : undefined}
        alt={title}
        sx={[styles.image, { objectFit: imageFit }]}
      />}
      <CardContent
        headingLevel={headingLevel}
        period={period}
        title={title}
        description={description}
        technologies={technologies}
        action={action}
      />
    </Box>
  );
}
