import { Box, Typography } from "@mui/material";
import { Link as RouterLink } from "react-router-dom";
import type { BrandProps } from "../../types";
import styles from "./styles";

export default function Brand({ name, signature, to, accessibleLabel }: BrandProps) {
  return (
    <Box component={RouterLink} to={to} aria-label={accessibleLabel} sx={styles.container}>
      <Box component="img" src={`${process.env.PUBLIC_URL || ""}/favicon.svg`} alt="" width={40} height={40} sx={styles.logo} />
      <Box sx={styles.details}>
        <Typography sx={styles.text}>{name}</Typography>
        <Typography sx={styles.signature}>{signature}</Typography>
      </Box>
    </Box>
  );
}
