import { Box, Typography } from "@mui/material";
import { motion, useReducedMotion } from "framer-motion";
import { Link as RouterLink } from "react-router-dom";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import Button from "@components/button";
import { routes } from "@navigations/routes";
import styles from "./styles";

export default function Hero() {
  const { t } = useTranslation(["home", "common"]);
  const reduced = useReducedMotion();
  return (
    <Box component="section" aria-labelledby="home-title" sx={styles.section}>
      <Container>
        <Box component={motion.div} initial={reduced ? false : { opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.4 }} sx={styles.content}>
          <Typography sx={styles.signature}>{t("common:brandSignature")}</Typography>
          <Typography sx={styles.greeting}>{t("home:hero.greeting")}</Typography>
          <Typography component="h1" id="home-title" sx={styles.title}>{t("home:hero.name")}</Typography>
          <Typography sx={styles.role}>{t("home:hero.specialty")}</Typography>
          <Typography sx={styles.description}>{t("home:hero.description")}</Typography>
          <Box sx={styles.actions}>
            <Button component={RouterLink} to={`${routes.home.path}#selected-projects`}>{t("home:hero.projects")}</Button>
            <Button customVariant="outlined" component={RouterLink} to={routes.contact.path}>{t("common:contactAction")}</Button>
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
