import { Box, Typography } from "@mui/material";
import { Link as RouterLink } from "react-router-dom";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import Button from "@components/button";
import SectionTitle from "@components/section_title";
import ResumeCard from "@components/resume_card";
import { projectData, getResumeEntries } from "data/resume";
import { routes, getProjectPath } from "@navigations/routes";
import styles from "./styles";
import { projectImageSources } from "@assets/projets/images";

export default function Projects() {
  const { t } = useTranslation(["projects", "common"]);
  const { t: cvT } = useTranslation("cv");
  const entries = getResumeEntries(projectData, cvT);
  return (
    <>
      <Box component="section" aria-label={t("projects:hero.title")} sx={styles.hero}>
        <Container>
          <SectionTitle titleLevel="h1" tone="dark" subtitle={t("projects:hero.subtitle")}
            title={t("projects:hero.title")} description={t("projects:hero.description")} sx={{ mb: 0 }} />
        </Container>
      </Box>
      <Box component="section" aria-label={t("projects:gallery.title")} sx={styles.section}>
        <Container>
          <SectionTitle subtitle={t("projects:gallery.subtitle")} title={t("projects:gallery.title")}
            description={t("projects:gallery.description")} />
          <Box sx={styles.grid}>
            {entries.map((entry) => (
              <Box component="article" key={entry.anchor} aria-label={entry.title} sx={styles.article}>
                <ResumeCard image={entry.image} imageLoading="lazy" imageFit="contain"
                  imageSrcSet={projectImageSources[entry.image]?.srcSet}
                  imageSizes="(min-width: 1440px) 656px, (min-width: 1200px) calc((100vw - 128px) / 2), (min-width: 900px) calc((100vw - 96px) / 2), (min-width: 600px) calc(100vw - 48px), calc(100vw - 32px)"
                  period={entry.period} title={entry.title} description={entry.description}
                  technologies={entry.technologies}
                  action={{ to: getProjectPath(entry.slug), label: t("projects:detailsAction") }} />
                <Button customVariant="text" component={RouterLink} to={`${routes.cv.path}#${entry.anchor}`}
                  aria-label={`${t("projects:information")} : ${entry.title}`} sx={{ minHeight: 48, mt: 1 }}>
                  {t("projects:information")}
                </Button>
              </Box>
            ))}
          </Box>
        </Container>
      </Box>
      <Box component="section" aria-labelledby="projects-collaboration" sx={styles.collaboration}>
        <Container>
          <Box sx={styles.callout}>
            <Typography component="h2" id="projects-collaboration" sx={styles.calloutTitle}>{t("projects:collaboration.title")}</Typography>
            <Typography sx={styles.calloutDescription}>{t("projects:collaboration.description")}</Typography>
            <Button component={RouterLink} to={routes.contact.path} sx={{ minWidth: 0 }}>{t("common:contactAction")}</Button>
          </Box>
        </Container>
      </Box>
    </>
  );
}
