import { projectData } from "./resume";

export type SkillCategoryId = "web" | "backend" | "mobile" | "databases" | "tools";
export type Skill = Readonly<{
  name: string;
  category: SkillCategoryId;
  evidence: "source" | "owner";
  preview?: boolean;
}>;

export const skillCategories: readonly SkillCategoryId[] = ["web", "backend", "mobile", "databases", "tools"];

// Owner declarations come from the P7 brief; only the three inspected frontend usages
// are marked as source-backed. This is provenance, never a proficiency rating.
export const skills: readonly Skill[] = [
  { name: "HTML", category: "web", evidence: "owner" },
  { name: "CSS", category: "web", evidence: "owner" },
  { name: "JavaScript", category: "web", evidence: "owner" },
  { name: "React", category: "web", evidence: "source", preview: true },
  { name: "TypeScript", category: "web", evidence: "source", preview: true },
  { name: "Material UI", category: "web", evidence: "source", preview: true },
  { name: "Node.js", category: "backend", evidence: "owner", preview: true },
  { name: "Express.js", category: "backend", evidence: "owner" },
  { name: "Python", category: "backend", evidence: "owner" },
  { name: "React Native", category: "mobile", evidence: "owner", preview: true },
  { name: "MongoDB", category: "databases", evidence: "owner" },
  { name: "MySQL", category: "databases", evidence: "owner" },
  { name: "Git", category: "tools", evidence: "owner" },
  { name: "GitHub", category: "tools", evidence: "owner" },
];

export function getSkillProjects(skill: Skill) {
  return projectData.filter((project) => project.technologies.includes(skill.name));
}
