import { Box, Typography } from "@mui/material";
import DescriptionOutlinedIcon from "@mui/icons-material/DescriptionOutlined";
import DownloadOutlinedIcon from "@mui/icons-material/DownloadOutlined";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import Button from "@components/button";
import { resumePdf } from "../../config";
import styles from "../../styles";

export default function Overview() {
  const { t } = useTranslation("cv");
  const information = [
    { label: t("overview.qualification"), value: `${t("presentation.formation-2.title")} · ISMTA, Foumban` },
    { label: t("overview.activity"), value: `${t("presentation.experience-1.title")} · ${t("entries.experience-1.period")}` },
    { label: t("overview.specialty"), value: t("hero.role") },
  ];
  return (
    <Box sx={styles.section}>
      <Container sx={styles.container}>
        <Box sx={styles.overview}>
          <Box component="section" aria-labelledby="cv-download-title" id="cv-download" tabIndex={-1} sx={styles.panel}>
            <DescriptionOutlinedIcon sx={styles.icon} />
            <Typography component="h2" id="cv-download-title" sx={styles.panelTitle}>{t("download.title")}</Typography>
            <Typography sx={styles.text}>{t("download.description")}</Typography>
            <Button<"a"> component="a" href={resumePdf.href} download={resumePdf.filename}
              startIcon={<DownloadOutlinedIcon />} aria-describedby="cv-download-note" sx={styles.button}>
              {t("download.action")}
            </Button>
            <Typography id="cv-download-note" sx={styles.note}>{t("download.note")}</Typography>
          </Box>
          <Box component="section" aria-labelledby="cv-information-title" sx={styles.panel}>
            <Typography component="h2" id="cv-information-title" sx={styles.panelTitle}>{t("overview.title")}</Typography>
            <Box component="dl" sx={styles.definitions}>
              {information.map((item) => (
                <Box key={item.label}>
                  <Typography component="dt" sx={styles.term}>{item.label}</Typography>
                  <Typography component="dd" sx={styles.value}>{item.value}</Typography>
                </Box>
              ))}
            </Box>
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
