import { Box, Typography } from "@mui/material";
import SocialButton from "@components/social_button";
import type { FooterSocialsProps } from "../../types";
import styles from "./styles";

export default function FooterSocials({ links, heading }: FooterSocialsProps) {
  return (
    <>
      <Typography sx={styles.title}>{heading}</Typography>
      <Box sx={styles.socials}>
        {links.map((item) => {
          const Icon = item.icon;
          return (
            <SocialButton key={item.id}>
              <Box component="a" href={item.href} aria-label={item.label} target="_blank" rel="noopener noreferrer" sx={styles.link}>
                <Icon />
              </Box>
            </SocialButton>
          );
        })}
      </Box>
    </>
  );
}
