import { Box } from "@mui/material";
import type { NavigationProps } from "../../types";
import NavigationItem from "../navigation_item";
import styles from "./styles";

export default function DesktopNavigation({ links, label }: NavigationProps) {
  return (
    <Box component="nav" aria-label={label} sx={styles.container}>
      {links.map((item) => <NavigationItem key={item.id} item={item} variant="desktop" />)}
    </Box>
  );
}
