import { Box, Typography } from "@mui/material";
import NorthEastIcon from "@mui/icons-material/NorthEast";
import Button from "@components/button";
import { Link as RouterLink } from "react-router-dom";
import styles from "./styles";

import type { CardContentProps } from "../../types";

export default function CardContent({ period, title, description, technologies, headingLevel, action }: CardContentProps) {
  return (
    <Box sx={styles.content}>
      <Typography sx={styles.period}>
        {period}
      </Typography>
      <Typography component={headingLevel} sx={styles.title}>
        {title}
      </Typography>
      <Typography sx={styles.description}>
        {description}
      </Typography>
      {Boolean(technologies?.length) && (
        <Box component="ul" sx={styles.technologies}>
          {technologies?.map((technology) => <Box component="li" key={technology} sx={styles.technology}>{technology}</Box>)}
        </Box>
      )}
      {action && <Button
        customVariant="text"
        sx={styles.button} component={RouterLink} to={action.to}
        aria-label={`${action.label} : ${title.trim()}`}
      >
        {action.label}
        <NorthEastIcon sx={styles.icon} />
      </Button>}
    </Box>
  );
}
