import type { TFunction } from "i18next";
import type { FooterConfig } from "../types";

export function getFooterConfig(t: TFunction<"common">): FooterConfig {
  return {
    brand: { name: "Assan Mbete", description: t("productDescription") },
    navigation: { heading: t("footer.navigation"), accessibleLabel: t("footer.navigationLabel") },
    socialsHeading: t("footer.socials"), location: t("footer.location"), copyright: t("footer.copyright"),
  };
}
