import { IconButton } from "@mui/material";
import MenuIcon from "@mui/icons-material/Menu";
import type { MobileButtonProps } from "../../types";
import styles from "./styles";

export default function MobileButton({ open, onOpen, label, controls }: MobileButtonProps) {
  return (
    <IconButton aria-controls={controls} aria-label={label} aria-expanded={open} sx={styles.button} onClick={onOpen}>
      <MenuIcon />
    </IconButton>
  );
}
