import { useId } from "react";
import { AppBar, Toolbar, Box } from "@mui/material";
import Container from "@components/container";
import useNavigation from "@navigations/use_navigation";
import { useTranslation } from "react-i18next";
import useLanguage from "./hooks/use_language";
import LanguageSwitcher from "./sub_components/language_switcher";
import { getHeaderConfig } from "./config";
import useHeader from "./hooks/use_header";
import Brand from "./sub_components/brand";
import DesktopNavigation from "./sub_components/desktop_navigation";
import MobileButton from "./sub_components/mobile_button";
import MobileDrawer from "./sub_components/mobile_drawer";
import styles from "./styles";

export default function Header() {
  const drawerId = useId();
  const { t } = useTranslation("common");
  const headerConfig = getHeaderConfig(t);
  const navigationLinks = useNavigation();
  const language = useLanguage();
  const { drawerOpen, openDrawer, closeDrawer } = useHeader();

  return (
    <>
      <Box component="a" href="#main-content" sx={styles.skipLink}
        onClick={(event) => {
          const main = document.getElementById("main-content");
          if (main) { event.preventDefault(); main.focus({ preventScroll: true }); }
        }}
      >{t("skipToContent")}</Box>
      <AppBar position="fixed" sx={styles.appBar}>
        <Container>
          <Toolbar disableGutters sx={styles.toolbar}>

            <Brand {...headerConfig.brand} />
            <DesktopNavigation
              links={navigationLinks}
              label={headerConfig.labels.desktopNavigation}
            />
            <Box sx={styles.desktopLanguage}><LanguageSwitcher {...language} /></Box>
            <MobileButton
              controls={drawerId}
              open={drawerOpen}
              onOpen={openDrawer}
              label={headerConfig.labels.openMenu}
            />
          </Toolbar>
        </Container>
      </AppBar>

      <MobileDrawer
        id={drawerId}
        brand={headerConfig.brand}
        open={drawerOpen}
        onClose={closeDrawer}
        links={navigationLinks}
        label={headerConfig.labels.mobileNavigation}
        closeLabel={headerConfig.labels.closeMenu}
        language={language}
      />
    </>
  );
}
