import useSeo from "@utils/seo/use_seo";
import { useLocation } from "react-router-dom";
import { useEffect, useRef } from "react";

export default function useMainLayout() {
  useSeo()
  const { pathname, hash } = useLocation()
  const mainRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const previous = window.history.scrollRestoration
    window.history.scrollRestoration = "manual"
    return () => { window.history.scrollRestoration = previous }
  }, [])

  useEffect(() => {
    const frame = window.requestAnimationFrame(() => {
      const main = mainRef.current
      if (!main) return
      let target: HTMLElement | null = null
      if (hash) {
        try { target = document.getElementById(decodeURIComponent(hash.slice(1))) }
        catch { /* A malformed fragment falls back to the page title. */ }
      }
      if (target && !main.contains(target)) target = null
      const heading = main.querySelector<HTMLElement>("h1")
      const focused = target || heading || main
      focused.setAttribute("tabindex", "-1")
      focused.focus({ preventScroll: true })

      const previous = document.documentElement.style.scrollBehavior
      document.documentElement.style.scrollBehavior = "auto"
      main.scrollTop = 0
      main.scrollLeft = 0
      if (target) target.scrollIntoView({ block: "start", behavior: "auto" })
      else window.scrollTo({ top: 0, left: 0, behavior: "auto" })
      document.documentElement.style.scrollBehavior = previous

    })
    return () => window.cancelAnimationFrame(frame)
  }, [pathname, hash])

  return { mainRef };
}
