import { Box } from "@mui/material";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import ResumeCard from "@components/resume_card";
import { educationData, getResumeEntries } from "data/resume";
import { learningAnchors } from "../../config";
import styles from "../../styles";
import sectionStyles from "../resume_section/styles";

export default function Complementary() {
  const { t } = useTranslation("cv");
  const entries = getResumeEntries(educationData, t).filter((entry) => learningAnchors.includes(entry.anchor));
  return (
    <Box component="section" aria-label={t("complementary.title")} sx={styles.section}>
      <Container sx={styles.container}>
        <SectionTitle subtitle={t("complementary.subtitle")} title={t("complementary.title")} sx={{ mb: 4 }} />
        <Box sx={sectionStyles.grid}>
          <Box component="article" aria-label={t("complementary.trainingTitle")} sx={styles.training}>
            <ResumeCard title={t("complementary.trainingTitle")} period={t("complementary.trainingPeriod")}
              description={t("complementary.trainingDescription")} />
          </Box>
          {entries.map((entry) => (
            <Box component="article" key={entry.anchor} id={entry.anchor} tabIndex={-1} aria-label={entry.title} sx={sectionStyles.article}>
              <ResumeCard title={entry.title} period={entry.period} description={entry.description} />
            </Box>
          ))}
        </Box>
      </Container>
    </Box>
  );
}
