import { useTranslation } from "react-i18next";
import { useId, useRef, useState } from "react";
import type { ChangeEvent, FormEvent } from "react";
import { useReducedMotion } from "framer-motion";
import { sendEmail } from "../../../services/email";
import { getContactConfig } from "../config";
import type { ContactController, ContactFieldIds, ContactFormData } from "../types";

export default function useContact(): ContactController {
  const { t } = useTranslation("contact");
  const contactConfig = getContactConfig(t);
  const [formData, setFormData] = useState<ContactFormData>(contactConfig.emptyFormData);
  const [loading, setLoading] = useState(false);
  const [successOpen, setSuccessOpen] = useState(false);
  const [error, setError] = useState<"validation" | "delivery" | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<keyof ContactFormData, "required" | "email">>>({});
  const sending = useRef(false);
  const validating = useRef(false);
  const formId = useId();
  const shouldReduceMotion = useReducedMotion();

  const fieldIds: ContactFieldIds = {
    name: `${formId}-name`,
    email: `${formId}-email`,
    subject: `${formId}-subject`,
    message: `${formId}-message`,
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = event.target;
    setFormData((current) => ({ ...current, [name]: value }));
    setFieldErrors((current) => ({ ...current, [name]: undefined }));
  };

  const handleInvalid = (event: FormEvent<HTMLFormElement>) => {
    if (!validating.current) return;
    const field = event.target as HTMLInputElement | HTMLTextAreaElement;
    const name = field.name as keyof ContactFormData;
    if (!(name in formData)) return;
    const code = field.validity.typeMismatch ? "email" : "required";
    setFieldErrors((current) => current[name] === code ? current : { ...current, [name]: code });
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (sending.current || loading) return;
    validating.current = true;
    const nativeValid = event.currentTarget.reportValidity();
    validating.current = false;
    if (!nativeValid) return;

    const validatedData: ContactFormData = {
      name: formData.name.trim(),
      email: formData.email.trim(),
      subject: formData.subject.trim(),
      message: formData.message.trim(),
    };
    const isValid = Boolean(
      validatedData.name &&
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(validatedData.email) &&
      validatedData.subject &&
      validatedData.message,
    );
    if (!isValid) {
      const errors: Partial<Record<keyof ContactFormData, "required" | "email">> = {};
      for (const name of Object.keys(validatedData) as (keyof ContactFormData)[]) {
        if (!validatedData[name]) errors[name] = "required";
      }
      if (validatedData.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(validatedData.email)) errors.email = "email";
      setFieldErrors(errors);
      setError("validation");
      const first = (Object.keys(errors) as (keyof ContactFormData)[])[0];
      if (first) (event.currentTarget.elements.namedItem(first) as HTMLElement | null)?.focus();
      return;
    }

    sending.current = true;
    try {
      setLoading(true);
      setError(null);
      setSuccessOpen(false);
      setFieldErrors({});
      await sendEmail(validatedData);
      setSuccessOpen(true);
      setFormData(contactConfig.emptyFormData);
    } catch {
      setError("delivery");
    } finally {
      sending.current = false;
      setLoading(false);
    }
  };

  const closeSuccess = () => setSuccessOpen(false);
  const closeError = () => setError(null);

  return {
    fields: {
      formData,
      fieldIds,
      labels: contactConfig.labels,
      disabled: loading,
      submitLabel: loading ? contactConfig.submitLabels.loading : contactConfig.submitLabels.idle,
      onChange: handleChange,
      onSubmit: handleSubmit,
      onInvalid: handleInvalid,
      fieldErrors: Object.fromEntries(Object.entries(fieldErrors).filter(([, code]) => code).map(([name, code]) => [name,
        code === "email" ? t("form.invalidEmail") : t("form.requiredField", { field: contactConfig.labels[name as keyof ContactFormData] }),
      ])),
      description: t("form.description"),
      requiredNote: t("form.requiredNote"),
    },
    information: contactConfig.information,
    map: contactConfig.map,
    success: {
      closeLabel: t("common:close"),
      open: successOpen,
      onClose: closeSuccess,
      message: contactConfig.feedback.successMessage,
      autoHideDuration: contactConfig.feedback.successDuration,
    },
    error: { closeLabel: t("common:close"), error: error === "validation" ? contactConfig.validationMessage : error === "delivery" ? t("feedback.error") : null, onClose: closeError, autoHideDuration: contactConfig.feedback.errorDuration },
    motion: {
      form: {
        ...contactConfig.animations.form,
        initial: shouldReduceMotion ? false : contactConfig.animations.form.initial,
        transition: shouldReduceMotion ? { duration: 0, delay: 0 } : contactConfig.animations.form.transition,
      },
      information: {
        ...contactConfig.animations.information,
        initial: shouldReduceMotion ? false : contactConfig.animations.information.initial,
        transition: shouldReduceMotion ? { duration: 0, delay: 0 } : contactConfig.animations.information.transition,
      },
    },
  };
}
