import { useTranslation } from "react-i18next";
import { useEffect, useRef } from "react";
import { Box, Typography } from "@mui/material";
import { isRouteErrorResponse, Link as RouterLink, useRouteError } from "react-router-dom";
import Button from "@components/button";
import useSeo from "@utils/seo/use_seo";

export default function ErrorPage({ notFound = false }: { notFound?: boolean }) {
  const { t } = useTranslation("common");
  const error: unknown = useRouteError();
  const missing = notFound || (isRouteErrorResponse(error) && error.status === 404);
  const title = missing ? t("errors.notFoundTitle") : t("errors.applicationTitle");
  useSeo(missing ? "notFound" : "error");
  const headingRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    headingRef.current?.focus({ preventScroll: true });
    const previous = document.documentElement.style.scrollBehavior;
    document.documentElement.style.scrollBehavior = "auto";
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
    document.documentElement.style.scrollBehavior = previous;
    if (process.env.NODE_ENV !== "production" && error) console.error(error);
  }, [title, error]);

  return (
    <Box sx={{ px: { xs: 2, md: 4 }, py: 8, textAlign: "center", backgroundColor: "background.default", color: "text.primary" }}>
      {missing && <Typography>404</Typography>}
      <Typography component="h1" variant="h2" ref={headingRef} tabIndex={-1}>{title}</Typography>
      <Typography sx={{ my: 3 }}>
        {missing
          ? t("errors.notFoundDescription")
          : t("errors.applicationDescription")}
      </Typography>
      <Button component={RouterLink} to="/">{t("errors.backHome")}</Button>
      {process.env.NODE_ENV !== "production" && Boolean(error) && (
        <Box component="details" sx={{ mt: 4, textAlign: "left" }}>
          <summary>{t("errors.technicalDetails")}</summary>
          <Box component="pre" sx={{ whiteSpace: "pre-wrap", overflowWrap: "anywhere" }}>
            {error instanceof Error ? error.stack || error.message : JSON.stringify(error, null, 2)}
          </Box>
        </Box>
      )}
    </Box>
  );
}
