import { useId, useState } from "react";
import { Box, Typography } from "@mui/material";
import { useTranslation } from "react-i18next";
import Button from "@components/button";
import styles from "./styles";
import type { ContactMapProps } from "../../types";

export default function ContactMap({ title, src }: ContactMapProps) {
  const { t } = useTranslation("contact");
  const [visible, setVisible] = useState(false);
  const mapId = useId();
  return (
    <Box component="section" aria-label={t("map.heading")} sx={styles.section}>
      <Typography component="h2" sx={styles.title}>{t("map.heading")}</Typography>
      <Typography sx={styles.description}>{t("map.description")}</Typography>
      <Button type="button" onClick={() => setVisible((current) => !current)}
        aria-expanded={visible} aria-controls={mapId} sx={styles.button}>
        {t(visible ? "map.hide" : "map.show")}
      </Button>
      <Box id={mapId}>
        {visible && <Box sx={styles.map}>
          <iframe title={title} width="100%" height="100%" loading="lazy" referrerPolicy="no-referrer" style={styles.frame} src={src} />
        </Box>}
      </Box>
    </Box>
  );
}
