export function getResumeEntries<T extends ResumeEntry>(entries: readonly T[], t: TFunction<"cv">): readonly (T & ResumeDisplayEntry)[] {
  return entries.map((entry) => ({
    ...entry,
    period: t(`entries.${entry.anchor}.period`),
    title: t(`entries.${entry.anchor}.title`),
    description: t(`entries.${entry.anchor}.description`),
  }));
}
