import { Link as RouterLink } from "react-router-dom";
import Button from "@components/button";
import { skills } from "data/skills";
import { routes } from "@navigations/routes";
import { Box, Typography } from "@mui/material";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import styles from "./styles";

export default function Skills() {
  const { t } = useTranslation("home");
  const { t: skillsT } = useTranslation("skills");
  const domains = (["web", "mobile", "backend"] as const).map((id) => ({
    id, technologies: skills.filter((skill) => skill.category === id && skill.preview).map((skill) => skill.name),
  }));
  return (
    <Box component="section" aria-label={t("skills.title")} sx={styles.section}>
      <Container>
        <SectionTitle subtitle={t("skills.subtitle")} title={t("skills.title")} description={t("skills.description")} />
        <Box component="ul" sx={styles.grid}>
          {domains.map((domain) => (
            <Box component="li" key={domain.id} sx={styles.card}>
              <Typography component="h3" sx={styles.title}>{t(`skills.${domain.id}`)}</Typography>
              <Typography sx={styles.technologies}>{domain.technologies.join(" · ")}</Typography>
            </Box>
          ))}
        </Box>
        <Typography sx={{ color: "text.secondary", mt: 3, lineHeight: 1.7 }}>{skillsT("previewNote")}</Typography>
        <Box sx={{ mt: 3 }}>
          <Button component={RouterLink} to={routes.skills.path} sx={{ minWidth: 0 }}>{skillsT("allAction")}</Button>
        </Box>
      </Container>
    </Box>
  );
}
