import { useTranslation } from "react-i18next";
import { educationData, getResumeEntries } from "data/resume";
import ResumeSection from "../resume_section";
import { academicAnchors } from "../../config";

export default function Education() {
  const { t } = useTranslation("cv");
  const available = getResumeEntries(educationData, t);
  const entries = academicAnchors.flatMap((anchor) => available.filter((entry) => entry.anchor === anchor))
    .map((entry) => ({ ...entry, title: t(`presentation.${entry.anchor}.title`), description: t(`presentation.${entry.anchor}.description`) }));
  return (
    <ResumeSection
      subtitle={t("cv:education.subtitle")}
      title={t("cv:education.title")}
      description={t("cv:education.description")}
      entries={entries}
    />
  );
}
