import { Box, Typography } from "@mui/material";
import { motion } from "framer-motion";
import SectionTitle from "@components/section_title";
import ResumeCard from "@components/resume_card";
import Container from "@components/container";
import useResumeSection from "./hooks/use_resume_section";
import styles from "./styles";
import type { ResumeSectionProps } from "./types";
import { projectImageSources } from "@assets/projets/images";

export default function ResumeSection({ subtitle, title, description, entries, showImages = false }: ResumeSectionProps) {
  const { getArticleMotion } = useResumeSection();

  return (
    <Box component="section" aria-label={title} sx={styles.section}>
      <Container sx={styles.content}>
        <SectionTitle subtitle={subtitle} title={title} description={description} sx={{ mb: 4 }} />
        <Box sx={styles.block}>
          <Box sx={styles.grid}>
            {entries.map((item, index) => (
              <Box
                key={item.id}
                component={motion.article}
                id={item.anchor}
                aria-label={item.title}
                tabIndex={-1}
                sx={styles.article}
                {...getArticleMotion(index)}
              >
                <ResumeCard
                  image={showImages ? item.image : undefined}
                  imageLoading="lazy"
                  imageSrcSet={showImages && item.image ? projectImageSources[item.image]?.srcSet : undefined}
                  imageSizes="(min-width: 1200px) 352px, (min-width: 952px) calc((100vw - 112px) / 3), (min-width: 900px) calc((100vw - 88px) / 2), (min-width: 632px) calc((100vw - 72px) / 2), (min-width: 600px) calc(100vw - 48px), calc(100vw - 32px)"
                  imageFit="contain"
                  period={item.period}
                  title={item.title}
                  description={item.description}
                  technologies={item.technologies}
                  action={item.action}
                />
                {item.note && <Typography sx={styles.note}>{item.note}</Typography>}
              </Box>
            ))}
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
