import type { TFunction } from "i18next";
import type { ContactConfig } from "../types";

export function getContactConfig(t: TFunction<"contact">): ContactConfig {
  return {
  emptyFormData: { name: "", email: "", subject: "", message: "" },
  labels: { title: t("form.title"), name: t("form.name"), email: t("form.email"), subject: t("form.subject"), message: t("form.message") },
  submitLabels: { idle: t("form.idle"), loading: t("form.loading") },
  validationMessage: t("form.validation"),
  information: { heading: t("information.heading"), email: "assanmbete00@gmail.com", location: t("common:footer.location"), phone: { label: "+237 657 53 43 92", href: "tel:+237657534392" } },
  map: {
    title: t("map.title"),
    src: "https://maps.google.com/maps?q=Yaoundé&t=&z=11&ie=UTF8&iwloc=&output=embed",
  },
  feedback: {
    successMessage: t("feedback.success"),
    successDuration: 5000,
    errorDuration: 6000,
  },
  animations: {
    form: {
      initial: false,
      whileInView: { opacity: 1, x: 0 },
      transition: { duration: 0.7 },
      viewport: { once: true },
    },
    information: {
      initial: false,
      whileInView: { opacity: 1, x: 0 },
      transition: { duration: 0.7, delay: 0.2 },
      viewport: { once: true },
    },
  },
};
}
