import type { TFunction } from "i18next";
import { routes } from "@navigations/routes";
import type { HeaderConfig } from "../types";

export function getHeaderConfig(t: TFunction<"common">): HeaderConfig {
  return {
    brand: { signature: t("brandSignature"), name: "Assan Mbete", to: routes.home.path, accessibleLabel: t("brandLabel") },
    labels: {
      desktopNavigation: t("mainNavigation"), mobileNavigation: t("mobileNavigation"),
      openMenu: t("openMenu"), closeMenu: t("closeMenu"),
    },
  };
}
