import { useEffect } from "react";
import { useLocation } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { getMetadata, applyMetadata, type SeoError } from "./metadata";

export default function useSeo(error?: SeoError) {
  const { pathname } = useLocation();
  const { t, i18n } = useTranslation("common");
  useEffect(() => {
    applyMetadata(getMetadata(pathname, t, error), i18n.resolvedLanguage || "fr");
  }, [pathname, t, i18n.resolvedLanguage, error]);
}
