import { useTranslation } from "react-i18next";
import { useReducedMotion } from "framer-motion";
import { projectData, getResumeEntries } from "data/resume";
import { routes } from "@navigations/routes";
import { resumePreviewConfig } from "../config";
import type { ResumePreview } from "../types";

export default function useResumePreview(): ResumePreview {
  const { t } = useTranslation(["cv", "home", "common"]);
  const reduced = useReducedMotion();
  // Feature Malentouen without mutating the shared project data.
  const entries = getResumeEntries(projectData, t).slice().sort((a, b) => Number(b.anchor === "projet-2") - Number(a.anchor === "projet-2"));
  return {
    heading: { subtitle: t("home:projects.subtitle"), title: t("home:projects.title"), description: t("home:projects.description") },
    sections: [{
      id: "projects", title: t("home:projects.selection"),
      entries: entries.slice(0, resumePreviewConfig.limit).map((entry, index) => ({
        ...entry, action: { to: `${routes.cv.path}#${entry.anchor}`, label: t("cv:actions.project") },
        motion: { initial: reduced ? false : { opacity: 0, y: 16 }, whileInView: { opacity: 1, y: 0 }, transition: { duration: reduced ? 0 : 0.35, delay: reduced ? 0 : index * 0.05 }, viewport: { once: true } },
      })),
      action: { to: `${routes.cv.path}#projet-2`, label: t("home:projects.resumeAction") },
    }],
  };
}
