import { Link as RouterLink } from "react-router-dom";
import { useTranslation } from "react-i18next";
import Button from "@components/button";
import { routes } from "@navigations/routes";
import { Box } from "@mui/material";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import useResumePreview from "./hooks/use_resume_preview";
import PreviewSection from "./sub_components/preview_section";
import styles from "./styles";

export default function Cv() {
  const { t } = useTranslation("home");
  const { heading, sections } = useResumePreview();
  return (
    <Box component="section" id="selected-projects" aria-label={heading.title} sx={styles.section}>
      <Container>
        <SectionTitle {...heading} sx={{ mb: 4 }} />
        {sections.map(({ id, ...section }) => <PreviewSection key={id} {...section} />)}
        <Box sx={{ mt: 4, textAlign: "center" }}>
          <Button component={RouterLink} to={routes.projects.path} sx={{ minWidth: 0 }}>{t("projects.allAction")}</Button>
        </Box>
      </Container>
    </Box>
  );
}
