import { Box, Typography } from "@mui/material";
import type { SxProps, Theme } from "@mui/material/styles";
import styles from "./styles";
import type { SectionTitleProps } from "./types";


export default function SectionTitle({
  subtitle,
  title,
  description,
  titleColor,
  titleLevel = "h2",
  tone = "light",
  sx,
}: SectionTitleProps) {
  const mergedSx = (
    sx
      ? [styles.container, ...(Array.isArray(sx) ? sx : [sx])]
      : styles.container
  ) as SxProps<Theme>;

  return (
    <Box sx={mergedSx} data-tone={tone}>
      {subtitle && <Typography sx={styles.subtitle}>{subtitle}</Typography>}

      <Typography
        component={titleLevel}
        sx={titleColor ? [styles.title, { color: titleColor }] : styles.title}
      >
        {title}
      </Typography>

      {description && (
        <Typography sx={styles.description}>{description}</Typography>
      )}
    </Box>
  );
}
