import { Box, Typography } from "@mui/material";
import { motion } from "framer-motion";
import { Link as RouterLink } from "react-router-dom";
import Button from "@components/button";
import ResumeCard from "@components/resume_card";
import type { PreviewSectionProps } from "./types";
import styles from "./styles";
import { projectImageSources } from "@assets/projets/images";

export default function PreviewSection({ title, entries, action }: PreviewSectionProps) {
  return (
    <Box sx={styles.block}>
      <Box sx={styles.blockHeader}>
        <Typography component="h3" sx={styles.blockTitle}>{title}</Typography>
        {action && (
          <Button
            customVariant="text"
            sx={styles.viewAll}
            component={RouterLink}
            to={action.to}
          >{" "}{action.label}{" "}</Button>
        )}
      </Box>
      <Box sx={styles.grid}>
        {entries.map((item) => {
          const imageSource = projectImageSources[item.image];
          // Cover can need more source pixels than the card width (260px frame height).
          const coverWidth = imageSource ? Math.ceil(260 * imageSource.width / imageSource.height) : 0;
          return (
            <Box key={item.id} component={motion.article} {...item.motion}>
              <ResumeCard
                headingLevel="h4"
                imageLoading="lazy"
                imageSrcSet={imageSource?.srcSet}
                imageSizes={`(min-width: 1440px) max(${coverWidth}px, 427px), (min-width: 1200px) max(${coverWidth}px, calc((100vw - 160px) / 3)), (min-width: 900px) max(${coverWidth}px, calc((100vw - 96px) / 2)), (min-width: 600px) max(${coverWidth}px, calc((100vw - 80px) / 2)), max(${coverWidth}px, calc(100vw - 32px))`}
                action={item.action}
                image={item.image}
                period={item.period}
                title={item.title}
                description={item.description}
              />
            </Box>
          );
        })}
      </Box>
    </Box>
  );
}
