import { Box, Typography } from "@mui/material";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import { educationData, experienceData, getResumeEntries } from "data/resume";
import styles from "./styles";

export default function Background() {
  const { t } = useTranslation("about");
  const { t: cvT } = useTranslation("cv");
  const anchors = ["formation-2", "experience-2", "experience-1"] as const;
  const available = getResumeEntries([...educationData, ...experienceData], cvT);
  const entries = anchors.flatMap((anchor) => available.filter((entry) => entry.anchor === anchor));
  const approach = ["interfaces", "solutions", "learning"] as const;
  return (
    <Box sx={styles.wrapper}>
      <Container>
        {entries.length > 0 && (
          <Box component="section" aria-label={t("background.title")} sx={styles.section}>
            <SectionTitle subtitle={t("background.subtitle")} title={t("background.title")} description={t("background.description")} />
            <Box component="ol" sx={styles.timeline}>
              {entries.map((entry) => (
                <Box component="li" key={entry.anchor} sx={styles.milestone}>
                  <Typography sx={styles.period}>{entry.period}</Typography>
                  <Typography component="h3" sx={styles.title}>{entry.title.trim()}</Typography>
                </Box>
              ))}
            </Box>
          </Box>
        )}
        <Box component="section" aria-label={t("approach.title")}>
          <SectionTitle subtitle={t("approach.subtitle")} title={t("approach.title")} />
          <Box sx={styles.grid}>
            {approach.map((id) => (
              <Box component="article" key={id} sx={styles.card}>
                <Typography component="h3" sx={styles.title}>{t(`approach.${id}.title`)}</Typography>
                <Typography sx={styles.text}>{t(`approach.${id}.description`)}</Typography>
              </Box>
            ))}
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
