import { useTranslation } from "react-i18next";
import { experienceData, getResumeEntries } from "data/resume";
import ResumeSection from "../resume_section";

export default function Experience() {
  const { t } = useTranslation("cv");
  return (
    <ResumeSection
      subtitle={t("cv:experience.subtitle")}
      title={t("cv:experience.title")}
      description={t("cv:experience.description")}
      entries={getResumeEntries(experienceData, t).map((entry) => ({
        ...entry, title: t(`presentation.${entry.anchor}.title`), description: t(`presentation.${entry.anchor}.description`),
      }))}
    />
  );
}
