import { Box, Typography } from "@mui/material";
import { EmailOutlined, LocationOnOutlined, PhoneOutlined } from "@mui/icons-material";
import { useTranslation } from "react-i18next";
import Button from "@components/button";
import { socials } from "@components/footer/config/socials";
import styles from "./styles";
import type { ContactInfoProps } from "../../types";

export default function ContactInfo({ heading, email, location, phone }: ContactInfoProps) {
  const { t } = useTranslation("contact");
  const networks = socials.filter((item) => item.href.startsWith("https://"));
  return (
    <Box component="section" aria-label={heading} sx={styles.card}>
      <Typography component="h2" sx={styles.title}>{heading}</Typography>
      <Box component="dl" sx={styles.details}>
        <Box sx={styles.detail}>
          <Typography component="dt" sx={styles.label}><EmailOutlined sx={styles.icon} />{t("information.email")}</Typography>
          <Box component="dd" sx={styles.definition}><Box component="a" href={`mailto:${email}`} sx={styles.link}>{email}</Box></Box>
        </Box>
        <Box sx={styles.detail}>
          <Typography component="dt" sx={styles.label}><PhoneOutlined sx={styles.icon} />{t("information.phone")}</Typography>
          <Box component="dd" sx={styles.definition}><Box component="a" href={phone.href} sx={styles.link}>{phone.label}</Box></Box>
        </Box>
        <Box sx={styles.detail}>
          <Typography component="dt" sx={styles.label}><LocationOnOutlined sx={styles.icon} />{t("information.location")}</Typography>
          <Typography component="dd" sx={styles.definition}>{location}</Typography>
        </Box>
      </Box>
      <Typography component="h3" sx={styles.socialTitle}>{t("information.socials")}</Typography>
      <Box component="nav" aria-label={t("information.socials")} sx={styles.socials}>
        {networks.map((item) => {
          const Icon = item.icon;
          return <Button<"a"> key={item.id} component="a" href={item.href} target="_blank" rel="noopener noreferrer"
            customVariant="text" startIcon={<Icon />} aria-label={t("information.newTab", { network: item.label })} sx={styles.socialLink}>{item.label}</Button>;
        })}
      </Box>
    </Box>
  );
}
