import type { NavigationLink } from "./types";

export const routes = {
  home: { path: "/", labelKey: "navigation.home", end: true },
  about: { path: "/about", labelKey: "navigation.about", end: false },
  cv: { path: "/cv", labelKey: "navigation.cv", end: false },
  projects: { path: "/projects", labelKey: "navigation.projects", end: false },
  skills: { path: "/skills", labelKey: "navigation.skills", end: false },
  contact: { path: "/contact", labelKey: "navigation.contact", end: false },
} as const satisfies Record<string, Omit<NavigationLink, "id" | "label">>;

// Projects and Skills are accessible from Home; header/footer links stay unchanged.
export const navigationLinks: readonly Omit<NavigationLink, "label">[] = Object.entries(routes).filter(([id]) => id !== "projects" && id !== "skills").map(
  ([id, route]) => ({ id, ...route }),
);


export const projectDetailRoute = `${routes.projects.path}/:slug`;

export function getProjectPath(slug: string): string {
  return `${routes.projects.path}/${encodeURIComponent(slug)}`;
}
