import { Box, Typography } from "@mui/material";
import { Link as RouterLink } from "react-router-dom";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import Button from "@components/button";
import { skills, skillCategories, getSkillProjects } from "data/skills";
import { projectData, getResumeEntries } from "data/resume";
import { routes, getProjectPath } from "@navigations/routes";
import styles from "./styles";

export default function Skills() {
  const { t } = useTranslation(["skills", "common"]);
  const { t: cvT } = useTranslation("cv");
  const projects = getResumeEntries(projectData, cvT);
  return (
    <>
      <Box component="section" aria-label={t("skills:hero.title")} sx={styles.hero}>
        <Container>
          <SectionTitle titleLevel="h1" tone="dark" subtitle={t("skills:hero.subtitle")} title={t("skills:hero.title")} description={t("skills:hero.description")} sx={{ mb: 0 }} />
        </Container>
      </Box>
      <Container>
        <Box sx={styles.content}>
          <Typography sx={styles.introduction}>{t("skills:sourceNote")}</Typography>
          {skillCategories.map((category) => (
            <Box component="section" key={category} aria-label={t(`skills:categories.${category}.title`)} sx={styles.section}>
              <SectionTitle title={t(`skills:categories.${category}.title`)} description={t(`skills:categories.${category}.description`)} sx={styles.categoryTitle} />
              <Box sx={styles.skillGrid}>
                {skills.filter((skill) => skill.category === category).map((skill) => {
                  const related = getSkillProjects(skill);
                  return (
                    <Box component="article" aria-label={skill.name} key={skill.name} sx={styles.skillCard}>
                      <Typography component="h3" sx={styles.cardTitle}>{skill.name}</Typography>
                      <Typography sx={styles.evidence}>{t(`skills:evidence.${skill.evidence}`)}</Typography>
                      {related.length > 0 && (
                        <Box component="ul" sx={styles.links}>
                          {related.map((project) => (
                            <Box component="li" key={project.slug}>
                              <Box component={RouterLink} to={getProjectPath(project.slug)} sx={styles.projectLink}
                                aria-label={`${cvT(`entries.${project.anchor}.title`)} — ${skill.name}`}>
                                {cvT(`entries.${project.anchor}.title`)}
                              </Box>
                              <Typography sx={styles.projectEvidence}>{t(`skills:projectEvidence.${project.technologyEvidence}`)}</Typography>
                            </Box>
                          ))}
                        </Box>
                      )}
                    </Box>
                  );
                })}
              </Box>
            </Box>
          ))}
          <Box component="section" aria-label={t("skills:projects.title")}>
            <SectionTitle title={t("skills:projects.title")} description={t("skills:projects.description")} />
            <Box sx={styles.grid}>
              {projects.map((project) => (
                <Box component="article" key={project.slug} sx={styles.card}>
                  <Typography component="h3" sx={styles.cardTitle}>{project.title}</Typography>
                  <Typography sx={styles.evidence}>{t(`skills:projectEvidence.${project.technologyEvidence}`)}</Typography>
                  <Typography sx={styles.projectTechnologies}>{project.technologies.join(" · ")}</Typography>
                  <Button customVariant="text" component={RouterLink} to={getProjectPath(project.slug)} sx={{ minHeight: 48 }} aria-label={`${t("skills:projects.action")} : ${project.title}`}>{t("skills:projects.action")}</Button>
                </Box>
              ))}
            </Box>
          </Box>
        </Box>
      </Container>
      <Box component="section" aria-label={t("skills:collaboration.title")} sx={styles.collaboration}>
        <Container>
          <SectionTitle tone="dark" title={t("skills:collaboration.title")} description={t("skills:collaboration.description")} sx={{ mb: 4 }} />
          <Button component={RouterLink} to={routes.contact.path} sx={{ minWidth: 0 }}>{t("common:contactAction")}</Button>
        </Container>
      </Box>
    </>
  );
}
