import { Alert, Snackbar } from "@mui/material";
import type { ErrorMessageProps } from "../../../../types";

export default function ErrorMessage({ error, onClose, autoHideDuration, closeLabel }: ErrorMessageProps) {
  return (
    <Snackbar
      open={Boolean(error)}
      autoHideDuration={autoHideDuration}
      onClose={onClose}
      anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
    >
      <Alert closeText={closeLabel} severity="error" variant="filled" onClose={onClose}>{error}</Alert>
    </Snackbar>
  );
}
