import { Box } from "@mui/material";
import { NavLink } from "react-router-dom";
import type { NavigationItemProps } from "../../types";
import styles from "./styles";

export default function NavigationItem({ item, variant, onNavigate }: NavigationItemProps) {
  return (
    <Box component={NavLink} to={item.path} end={item.end} onClick={onNavigate} sx={styles[variant]}>
      {item.label}
    </Box>
  );
}
