import { useTranslation } from "react-i18next";
import { Box, Typography } from "@mui/material";
import { motion, useReducedMotion } from "framer-motion";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import styles from "./styles";

import { interests } from "./config";


export default function Interests() {
  const { t } = useTranslation(["about", "common"]);
  const shouldReduceMotion = useReducedMotion();
  return (
    <Box component="section" aria-label={t("about:interests.title")} sx={styles.section}>
      <Container>
        <SectionTitle
          subtitle={t("about:interests.subtitle")}
          title={t("about:interests.title")}
        />

        <Box component="ul" sx={styles.grid}>
          {interests.map((item, index) => (
            <Box
              component={motion.li}
              key={item.id}
              sx={styles.card}
              initial={shouldReduceMotion ? false : { opacity: 0, y: 12 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={shouldReduceMotion ? { duration: 0, delay: 0 } : { duration: 0.3, delay: index * 0.04 }}
              viewport={{ once: true }}
            >
              <Typography sx={styles.text}>
                {t(item.labelKey)}
              </Typography>
            </Box>
          ))}
        </Box>
      </Container>
    </Box>
  );
}