import { Box, Typography } from "@mui/material";
import { NavLink } from "react-router-dom";
import type { FooterNavigationProps } from "../../types";
import styles from "./styles";

export default function FooterNavigation({ links, heading, accessibleLabel }: FooterNavigationProps) {
  return (
    <Box>
      <Typography sx={styles.title}>{heading}</Typography>
      <Box component="nav" aria-label={accessibleLabel} sx={styles.navigation}>
        {links.map((item) => (
          <Box component={NavLink} key={item.id} to={item.path} end={item.end} sx={styles.link}>
            {item.label}
          </Box>
        ))}
      </Box>
    </Box>
  );
}
