import { Box, Typography } from "@mui/material";
import { Link as RouterLink } from "react-router-dom";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import Button from "@components/button";
import { skills, skillCategories } from "data/skills";
import { routes } from "@navigations/routes";
import styles from "../../styles";

export default function SkillsSummary() {
  const { t } = useTranslation(["cv", "skills"]);
  return (
    <Box component="section" aria-label={t("cv:skillsSummary.title")} sx={styles.section}>
      <Container sx={styles.container}>
        <SectionTitle subtitle={t("cv:skillsSummary.subtitle")} title={t("cv:skillsSummary.title")}
          description={t("cv:skillsSummary.description")} sx={{ mb: 4 }} />
        <Box sx={styles.skills}>
          {skillCategories.map((category) => (
            <Box component="article" key={category} aria-label={t(`skills:categories.${category}.title`)} sx={styles.panel}>
              <Typography component="h3" sx={styles.skillTitle}>{t(`skills:categories.${category}.title`)}</Typography>
              {(["source", "owner"] as const).map((evidence) => {
                const entries = skills.filter((skill) => skill.category === category && skill.evidence === evidence);
                return entries.length > 0 && (
                  <Box key={evidence} sx={styles.evidenceGroup}>
                    <Typography sx={styles.evidence}>{t(`cv:skillsSummary.${evidence}`)}</Typography>
                    <Box component="ul" aria-label={t(`cv:skillsSummary.${evidence}`)} sx={styles.technologies}>
                      {entries.map((skill) => <Box component="li" key={skill.name} sx={styles.technology}>{skill.name}</Box>)}
                    </Box>
                  </Box>
                );
              })}
            </Box>
          ))}
        </Box>
        <Button customVariant="text" component={RouterLink} to={routes.skills.path} sx={styles.button}>{t("cv:skillsSummary.action")}</Button>
      </Container>
    </Box>
  );
}
