import { useTranslation } from "react-i18next";
import { Box } from "@mui/material";
import { motion, useReducedMotion } from "framer-motion";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import styles from "./styles";
import { images } from "./data";


export default function Gallery() {
  const { t } = useTranslation(["about", "common"]);
  const shouldReduceMotion = useReducedMotion();
  return (
    <Box component="section" aria-label={t("about:gallery.title")} sx={styles.section}>
      <Container>
        <SectionTitle
          subtitle={t("about:gallery.subtitle")}
          title={t("about:gallery.title")}
          description={t("about:gallery.description")}
        />

        <Box sx={styles.grid}>
          {images.map((image, index) => (
            <Box
              key={image.id}
              component={motion.figure}
              sx={styles.imageWrapper}
              initial={shouldReduceMotion ? false : { opacity: 0, y: 12 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={shouldReduceMotion ? { duration: 0, delay: 0 } : { duration: 0.3, delay: index * 0.04 }}
              viewport={{ once: true }}
            >
              <Box
                component="img"
                src={image.src}
                loading="lazy"
                decoding="async"
                srcSet={image.srcSet}
                sizes={image.srcSet ? "(min-width: 1440px) 432px, (min-width: 1200px) calc((100vw - 144px) / 3), (min-width: 900px) calc((100vw - 112px) / 3), (min-width: 600px) calc((100vw - 72px) / 2), calc(100vw - 32px)" : undefined}
                alt={t(`about:${image.altKey}`)}
                sx={[styles.image, { aspectRatio: `${image.width} / ${image.height}` }]}
              />
            </Box>
          ))}
        </Box>
      </Container>
    </Box>
  );
}
