import type { TFunction } from "i18next";
import { matchPath } from "react-router-dom";
import { projectData } from "data/resume";
import { routes, getProjectPath, projectDetailRoute } from "@navigations/routes";
import { heroConfig } from "@pages/about/sub_components/hero/config";
import { SITE_URL, SOCIAL_IMAGE_URL } from "./config";

export type SeoError = "notFound" | "error";

export function getMetadata(pathname: string, t: TFunction, error?: SeoError) {
  const path = pathname.replace(/\/+$/, "") || routes.home.path;
  const routeEntry = Object.entries(routes).find(([, route]) => matchPath(route.path, path));
  const route = routeEntry?.[0];
  let slug = matchPath(projectDetailRoute, path)?.params.slug;
  try { slug = slug ? decodeURIComponent(slug) : undefined; }
  catch { slug = undefined; }
  const project = projectData.find((entry) => entry.slug === slug);
  const missing = error || (!route && !project ? "notFound" : undefined);
  const name = t("home:hero.name");
  const profession = t("home:hero.specialty");
  const page = missing
    ? t(missing === "notFound" ? "errors.notFoundTitle" : "errors.applicationTitle")
    : project ? t(`cv:entries.${project.anchor}.title`) : t(`navigation.${route}`);
  const descriptions: Record<string, string> = {
    home: t("home:hero.description"),
    about: t("about:hero.summary", { city: heroConfig.city }),
    projects: t("projects:hero.description"),
    skills: t("skills:hero.description"),
    cv: t("cv:hero.description"),
    contact: t("contact:hero.description"),
  };
  const description = missing
    ? t(missing === "notFound" ? "errors.notFoundDescription" : "errors.applicationDescription")
    : project ? (project.overviewKey ? t(`projects:${project.overviewKey}`) : t("seo.lapnombaPayDescription"))
      : descriptions[route!];
  const canonicalPath = project ? getProjectPath(project.slug) : routeEntry?.[1].path;
  return {
    title: t(route === "home" && !missing ? "metadataTitle" : "seo.pageTitle", { name, page: route === "home" && !missing ? profession : page }),
    description,
    canonical: missing ? undefined : new URL(canonicalPath === "/" ? "" : canonicalPath!.slice(1), SITE_URL).href,
    image: SOCIAL_IMAGE_URL,
    imageAlt: t("portrait"),
    name,
    person: missing ? undefined : {
      "@context": "https://schema.org",
      "@type": "Person",
      "@id": `${SITE_URL}#person`,
      name,
      jobTitle: profession,
      url: SITE_URL,
    },
  };
}

// Reuse initial HTML tags; remove duplicates only for the SEO fields we own.
function singleton(selector: string, create: () => HTMLElement) {
  const [first, ...duplicates] = Array.from(document.head.querySelectorAll<HTMLElement>(selector));
  duplicates.forEach((element) => element.remove());
  const element = first || create();
  if (!first) document.head.appendChild(element);
  return element;
}

export function applyMetadata(metadata: ReturnType<typeof getMetadata>, language: string) {
  const lang = language.split("-")[0] === "en" ? "en" : "fr";
  document.title = metadata.title;
  document.documentElement.lang = lang;
  const meta = (attribute: "name" | "property", key: string, content?: string) => {
    const selector = `meta[${attribute}="${key}"]`;
    if (content === undefined) {
      document.head.querySelectorAll(selector).forEach((element) => element.remove());
      return;
    }
    const element = singleton(selector, () => {
      const element = document.createElement("meta");
      element.setAttribute(attribute, key);
      return element;
    });
    element.setAttribute("content", content);
  };
  meta("name", "description", metadata.description);
  meta("name", "robots", metadata.canonical ? undefined : "noindex, follow");
  meta("property", "og:type", "website");
  meta("property", "og:site_name", metadata.name);
  meta("property", "og:title", metadata.title);
  meta("property", "og:description", metadata.description);
  meta("property", "og:url", metadata.canonical);
  meta("property", "og:image", metadata.image);
  meta("property", "og:image:type", "image/jpeg");
  meta("property", "og:image:width", "853");
  meta("property", "og:image:height", "1280");
  meta("property", "og:image:alt", metadata.imageAlt);
  meta("property", "og:locale", lang === "en" ? "en_US" : "fr_FR");
  meta("name", "twitter:card", "summary");
  meta("name", "twitter:title", metadata.title);
  meta("name", "twitter:description", metadata.description);
  meta("name", "twitter:image", metadata.image);
  meta("name", "twitter:image:alt", metadata.imageAlt);
  if (metadata.canonical) {
    const canonical = singleton('link[rel="canonical"]', () => {
      const element = document.createElement("link");
      element.setAttribute("rel", "canonical");
      return element;
    });
    canonical.setAttribute("href", metadata.canonical);
  } else document.head.querySelectorAll('link[rel="canonical"]').forEach((element) => element.remove());
  if (metadata.person) {
    const script = singleton('script[data-portfolio-seo="person"]', () => {
      const element = document.createElement("script");
      element.setAttribute("type", "application/ld+json");
      element.setAttribute("data-portfolio-seo", "person");
      return element;
    });
    script.textContent = JSON.stringify(metadata.person);
  } else document.head.querySelectorAll('script[data-portfolio-seo="person"]').forEach((element) => element.remove());
}
