import emailjs from "@emailjs/browser";
import type { EmailDeliveryReceipt, EmailMessage } from "./types";
import { emailConfig } from "./config";

export const EMAIL_SEND_ERROR_FALLBACK = "Une erreur est survenue lors de l'envoi du message.";

function normalizeEmailError(error: unknown): Error {
  if (error instanceof Error) return error;
  if (typeof error === "string") return new Error(error, { cause: error });
  if (error && typeof error === "object") {
    if ("text" in error && typeof error.text === "string") {
      return new Error(error.text, { cause: error });
    }
    if ("message" in error && typeof error.message === "string") {
      return new Error(error.message, { cause: error });
    }
  }
  return new Error(EMAIL_SEND_ERROR_FALLBACK, { cause: error });
}

export async function sendEmail({
  name,
  email,
  subject,
  message,
}: EmailMessage): Promise<EmailDeliveryReceipt> {
  try {
    return await emailjs.send(
      emailConfig.serviceId,
      emailConfig.templateId,
      {
        from_name: name,
        from_email: email,
        subject,
        message,
        to_email: emailConfig.recipientEmail,
      },
      emailConfig.publicKey
    );
  } catch (error: unknown) {
    throw normalizeEmailError(error);
  }
}
