import { Box, Drawer, IconButton } from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import type { MobileDrawerProps } from "../../types";
import Brand from "../brand";
import NavigationItem from "../navigation_item";
import LanguageSwitcher from "../language_switcher";
import styles from "./styles";

export default function MobileDrawer({ id, brand, open, onClose, links, label, closeLabel, language }: MobileDrawerProps) {
  return (
    <Drawer anchor="right" open={open} onClose={onClose} ModalProps={{ keepMounted: true }} slotProps={{ paper: { id, sx: styles.paper, "aria-label": label } }}>
      <Box sx={styles.header}>
        <Box onClick={onClose}><Brand {...brand} /></Box>
        <IconButton sx={{ width: 48, height: 48 }} aria-label={closeLabel} onClick={onClose}><CloseIcon /></IconButton>
      </Box>
      <Box component="nav" aria-label={label} sx={styles.navigation}>
        {links.map((item) => (
          <NavigationItem key={item.id} item={item} variant="mobile" onNavigate={onClose} />
        ))}
      </Box>
      <Box sx={styles.language}><LanguageSwitcher {...language} /></Box>
    </Drawer>
  );
}
