import { useTranslation } from "react-i18next";
import { projectData, getResumeEntries } from "data/resume";
import ResumeSection from "../resume_section";
import { getProjectPath } from "@navigations/routes";

export default function Projects() {
  const { t } = useTranslation(["cv", "skills"]);
  return (
    <ResumeSection
      subtitle={t("cv:projects.subtitle")}
      title={t("cv:projects.title")}
      description={t("cv:projects.description")}
      showImages
      entries={getResumeEntries(projectData, t).map((entry) => ({
        ...entry,
        action: { to: getProjectPath(entry.slug), label: t("cv:actions.project") },
        note: t(`skills:projectEvidence.${entry.technologyEvidence}`),
      }))}
    />
  );
}
