import { Box, CircularProgress, Stack, TextField, Typography } from "@mui/material";
import CustomButton from "@components/button";
import { SendOutlined } from "@mui/icons-material";
import type { FormFieldsProps } from "../../../../types";
import styles from "./styles";

export default function FormFields({
  formData,
  fieldIds,
  labels,
  submitLabel,
  disabled,
  onChange,
  onSubmit,
  onInvalid,
  fieldErrors,
  description,
  requiredNote,
}: FormFieldsProps) {
  return (
    <Box
      component="form"
      noValidate
      onSubmit={onSubmit}
      onInvalid={onInvalid}
      aria-labelledby={`${fieldIds.name}-title`}
      aria-describedby={`${fieldIds.name}-description ${fieldIds.name}-required`}
      aria-busy={disabled}
    >
      <Typography component="h2" id={`${fieldIds.name}-title`} sx={styles.title}>{labels.title}</Typography>
      <Typography id={`${fieldIds.name}-description`} sx={styles.description}>{description}</Typography>
      <Typography id={`${fieldIds.name}-required`} sx={styles.required}>{requiredNote}</Typography>

      <Stack direction="column" spacing={0}>
        <Box sx={styles.field}>
          <Typography component="label" htmlFor={fieldIds.name} sx={styles.label}>{labels.name}</Typography>

          <TextField
            fullWidth
            name="name"
            id={fieldIds.name}
            required
            disabled={disabled}
            error={Boolean(fieldErrors.name)}
            helperText={fieldErrors.name}
            autoComplete="name"
            value={formData.name}
            onChange={onChange}
            sx={styles.input}
          />
        </Box>

        <Box sx={styles.field}>
          <Typography component="label" htmlFor={fieldIds.email} sx={styles.label}>{labels.email}</Typography>

          <TextField
            fullWidth
            name="email"
            id={fieldIds.email}
            type="email"
            required
            disabled={disabled}
            error={Boolean(fieldErrors.email)}
            helperText={fieldErrors.email}
            autoComplete="email"
            value={formData.email}
            onChange={onChange}
            sx={styles.input}
          />
        </Box>
      </Stack>

      <Box>
        <Typography component="label" htmlFor={fieldIds.subject} sx={styles.label}>{labels.subject}</Typography>

        <TextField
          fullWidth
          name="subject"
          id={fieldIds.subject}
          required
          disabled={disabled}
          error={Boolean(fieldErrors.subject)}
          helperText={fieldErrors.subject}
          value={formData.subject}
          onChange={onChange}
          sx={styles.input}
        />
      </Box>

      <Box>
        <Typography component="label" htmlFor={fieldIds.message} sx={styles.label}>{labels.message}</Typography>

        <TextField
          fullWidth
          multiline
          rows={6}
          name="message"
          id={fieldIds.message}
          required
          disabled={disabled}
          error={Boolean(fieldErrors.message)}
          helperText={fieldErrors.message}
          value={formData.message}
          onChange={onChange}
          sx={styles.input}
        />
      </Box>

      <Box sx={styles.actions}>
        <CustomButton
          type="submit"
          customVariant="contained"
          disabled={disabled}
          endIcon={disabled ? <CircularProgress size={18} color="inherit" aria-hidden="true" /> : <SendOutlined />}
          sx={styles.submitButton}
        >
          {submitLabel}
        </CustomButton>
      </Box>
    </Box>
  );
}
