import { useReducedMotion, type MotionProps } from "framer-motion";

export default function useResumeSection() {
  const shouldReduceMotion = useReducedMotion();

  const getArticleMotion = (index: number): MotionProps => ({
    initial: false,
    whileInView: { y: 0 },
    transition: shouldReduceMotion
      ? { duration: 0, delay: 0 }
      : { duration: 0.25, delay: Math.min(index, 2) * 0.05 },
    viewport: { once: true },
  });

  return { getArticleMotion };
}
