import { Box, Typography } from "@mui/material";
import { motion } from "framer-motion";
import Container from "@components/container";
import useContact from "../../hooks/use_contact";
import ContactInfo from "../contact_infos";
import ContactMap from "../contact_map";
import FormFields from "./sub_components/form_fields";
import SuccessMessage from "./sub_components/success_message";
import ErrorMessage from "./sub_components/error_message";
import styles from "./styles";

export default function ContactForm() {
  const { fields, success, error, information, map, motion: animations } = useContact();
  return (
    <Box sx={styles.section}>
      <Container sx={styles.content}>
        <Box sx={styles.container}>
          <Box component={motion.div} sx={styles.information} {...animations.information}>
            <ContactInfo {...information} />
          </Box>
          <Box component={motion.div} sx={styles.formCard} {...animations.form}>
            <FormFields {...fields} />
            {fields.disabled && <Typography role="status" aria-live="polite" sx={styles.progress}>{fields.submitLabel}</Typography>}
          </Box>
        </Box>
        <ContactMap {...map} />
        <SuccessMessage {...success} />
        <ErrorMessage {...error} />
      </Container>
    </Box>
  );
}
