import { useTranslation } from "react-i18next";
import type { LanguageSwitcherProps } from "../types";
import type { SupportedLanguage } from "../../../i18n/types";

export default function useLanguage(): LanguageSwitcherProps {
  const { t, i18n } = useTranslation("common");
  const value: SupportedLanguage = i18n.resolvedLanguage === "en" ? "en" : "fr";
  const onChange = (language: SupportedLanguage) => { void i18n.changeLanguage(language); };
  return { value, onChange, label: t("language") };
}
