import Snackbar from "@mui/material/Snackbar";
import Alert from "@mui/material/Alert";

import type { SuccessMessageProps } from "../../../../types";

export default function SuccessMessage({
  closeLabel,
  open,
  onClose,
  message,
  autoHideDuration,
}: SuccessMessageProps) {
  return (
    <Snackbar
      open={open}
      autoHideDuration={autoHideDuration}
      onClose={onClose}
      anchorOrigin={{
        vertical: "bottom",
        horizontal: "center",
      }}
    >
      <Alert
        closeText={closeLabel}
        onClose={onClose}
        role="status"
        aria-live="polite"
        severity="success"
        variant="filled"
      >
        {message}
      </Alert>
    </Snackbar>
  );
}
