import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { Box, Typography } from "@mui/material";
import { useParams, Link as RouterLink } from "react-router-dom";
import { useTranslation } from "react-i18next";
import Container from "@components/container";
import SectionTitle from "@components/section_title";
import Button from "@components/button";
import ErrorPage from "@pages/error";
import { projectData, getResumeEntries } from "data/resume";
import { routes } from "@navigations/routes";
import styles from "./styles";
import { projectImageSources } from "@assets/projets/images";

export default function ProjectDetail() {
  const { slug } = useParams();
  const { t } = useTranslation("projects");
  const { t: cvT } = useTranslation("cv");
  const source = projectData.find((entry) => entry.slug === slug);
  if (!source) return <ErrorPage notFound />;
  const project = getResumeEntries([source], cvT)[0];
  const imageSource = projectImageSources[project.image];
  const confirmed = project.technologyEvidence !== "description";

  return (
    <>
      <Box component="section" aria-label={project.title} sx={styles.hero}>
        <Container>
          <Box sx={styles.heroContent}>
            <Button customVariant="text" component={RouterLink} to={routes.projects.path}
              startIcon={<ArrowBackIcon />} sx={styles.backLink}>{t("detail.backToProjects")}</Button>
            <SectionTitle titleLevel="h1" tone="dark" subtitle={project.period}
              title={project.title} description={project.description} sx={styles.heroHeading} />
            {project.technologies.length > 0 && (
              <Box component="section" aria-label={t(confirmed ? "detail.confirmedTechnologies" : "detail.mentionedTechnologies")} sx={styles.technologySection}>
                <Typography component="h2" sx={styles.technologyTitle}>{t(confirmed ? "detail.confirmedTechnologies" : "detail.mentionedTechnologies")}</Typography>
                <Box component="ul" sx={styles.technologies}>
                  {project.technologies.map((technology) => <Box component="li" key={technology} sx={styles.technology}>{technology}</Box>)}
                </Box>
                {!confirmed && <Typography sx={styles.note}>{t("detail.technologyNote")}</Typography>}
              </Box>
            )}
            <Box component="figure" sx={styles.figure}>
              <Box component="img" src={project.image} srcSet={imageSource?.srcSet}
                sizes={imageSource?.srcSet ? "(min-width: 1164px) 1100px, (min-width: 900px) calc(100vw - 64px), (min-width: 600px) calc(100vw - 48px), calc(100vw - 32px)" : undefined}
                loading="eager" decoding="async"
                alt={project.imageDescriptionKey ? t(project.imageDescriptionKey) : t("detail.screenshotAlt", { name: project.title })}
                sx={[styles.image, { aspectRatio: imageSource ? `${imageSource.width} / ${imageSource.height}` : undefined }]} />
              {project.imageDescriptionKey && <Typography component="figcaption" sx={styles.imageCaption}>{t(project.imageDescriptionKey)}</Typography>}
            </Box>
          </Box>
        </Container>
      </Box>
      <Container>
        <Box sx={styles.content}>
          {project.overviewKey && (
            <Box component="section" aria-label={t("detail.overviewTitle")} sx={styles.section}>
              <SectionTitle title={t("detail.overviewTitle")} sx={{ mb: 3 }} />
              <Typography sx={styles.text}>{t(project.overviewKey)}</Typography>
            </Box>
          )}
          <Box component="nav" aria-label={t("detail.navigation")} sx={styles.navigation}>
            <Button component={RouterLink} to={routes.projects.path} sx={{ minWidth: 0 }}>{t("detail.backToProjects")}</Button>
            <Button customVariant="text" component={RouterLink} to={`${routes.cv.path}#${project.anchor}`} sx={{ minHeight: 48 }}>{t("detail.cvInformation")}</Button>
          </Box>
        </Box>
      </Container>
    </>
  );
}
